using System.Collections.Generic;
using System.Linq;
using BepInEx;
using BepInEx.Configuration;
using HarmonyLib;
using UnityEngine;

namespace SlotMachine
{
    /// <summary>
    /// A buildable slot machine, Odin's Fortune. Build it at a workbench (Fine Wood, Bronze and Stone), then put
    /// coins in: three reels spin, and a win is spat out of the tray. Over time it gives back about 93% of what goes in.
    ///
    /// Split across files: Plugin.cs (setup, registering the piece), ModelData.cs (the look, generated by tools/modelkit),
    /// ModelBuilder.cs and Look.cs (turning it into game objects), Icon.cs (the build-menu picture), Payout.cs (the odds),
    /// Machine.cs (the piece: pulling, spinning, paying).
    /// </summary>
    [BepInPlugin(Guid, Name, Version)]
    public class Plugin : BaseUnityPlugin
    {
        public const string Guid = "com.quad.slotmachine";
        public const string OldGuid = "com.dhack.slotmachine"; // (its id until 2026-10: settings move over by themselves, see Shared/Migration.cs)
        public const string Name = "SlotMachine";
        public const string Version = "1.2.3";
        public const string PiecePrefab = "piece_slotmachine";

        internal static ConfigEntry<int> Bet, PayoutPercent;
        internal static ConfigEntry<string> Cost;
        internal static BepInEx.Logging.ManualLogSource Log;
        /// <summary>What a slot machine costs before anyone changes it.</summary>
        internal const string DefaultCost = "FineWood:15, Bronze:8, Stone:10";
        private static bool _tellNoServer;   // the server hasn't the mod: say so once the player is in the world
        internal static DHack.Shared.ServerSettings Synced; // the prizes and the cost are the server's in multiplayer (or each player could set their own)
        private static readonly int[] Bets = { 5, 10, 25, 50, 100 };

        private static GameObject _holder, _prefab;
        // The build-menu list it was put on, kept to take it off again: at the main menu (a reload there) the hammer can't be looked up,
        // and a destroyed piece left on the list made every change to the player's bag throw, half-way through crafting (free crafts).
        private static PieceTable _table;
        private Harmony _harmony;

        private void Awake()
        {
            DHack.Shared.Migration.FromOldGuid(this, OldGuid); // first: before any setting is read
            DHack.Shared.Translations.Load(this);   // translations/*.json: its words in the player's language
            Log = Logger;
            Synced = new DHack.Shared.ServerSettings(Guid, Config, Logger);
            Bet = Config.Bind("Play", "Bet", 10, new ConfigDescription("Coins per pull (change it at the machine with the alternate-use key + use).", new AcceptableValueList<int>(Bets)));
            PayoutPercent = Synced.Add(Config.Bind("Play", "PayoutPercent", 100, new ConfigDescription("Scales every prize (100 = standard, which returns about 93% over time; 50 = half the prizes; above 107 the machine pays out more than goes in). In multiplayer the server's value applies.", new AcceptableValueRange<int>(10, 300))));
            Cost = Synced.Bind("Building", "Cost", DefaultCost, "What a slot machine costs to build with the hammer (at a workbench). " + DHack.Shared.Costs.Help);
            Cost.SettingChanged += (s, e) => ApplyCost();
            Synced.ServerChanged += () => _tellNoServer = Synced.Server == DHack.Shared.ServerSettings.ServerMod.Missing;

            _harmony = new Harmony(Guid);
            _harmony.PatchAll();
            if (ZNetScene.instance != null) Register(ZNetScene.instance); // hot reload while in a world
            Logger.LogInfo($"{Name} {Version} loaded");
        }

        private void Update()
        {
            Synced?.Update(); // notices joining and leaving a server, for the settings it decides
            if (_tellNoServer && Player.m_localPlayer != null)
            {
                _tellNoServer = false;
                Player.m_localPlayer.Message(MessageHud.MessageType.Center, "$slotmachine_server_missing");
            }
        }

        private void OnDestroy()
        {
            _harmony?.UnpatchSelf();
            Unregister();
            Synced?.Dispose();
            DHack.Shared.Translations.Unload();
        }

        internal static void NextBet()
        {
            int i = System.Array.IndexOf(Bets, Bet.Value);
            Bet.Value = Bets[(i + 1) % Bets.Length];
        }

        internal static void Register(ZNetScene scene)
        {
            GameObject source = scene.GetPrefab("piece_chest_wood");
            GameObject hammer = scene.GetPrefab("Hammer"); // items are in the scene too, and ObjectDB may not be awake yet
            GameObject bench = scene.GetPrefab("piece_workbench");
            if (source == null || hammer == null) { Debug.LogWarning(Name + ": chest or hammer prefab not found"); return; }

            if (_prefab == null)
            {
                _holder = new GameObject(Name + "Prefabs");
                _holder.SetActive(false); // keeps the copy from waking up as a real object
                Object.DontDestroyOnLoad(_holder);
                // The look can fail (a game update renames a material) but the piece must still be registered, or the host deletes the placed ones.
                try { Look.Harvest(scene, source.GetComponentInChildren<Renderer>(true).sharedMaterial); }
                catch (System.Exception e) { Debug.LogWarning($"{Name}: could not gather the materials for its look: {e.Message}"); }
                _prefab = Make(source, bench != null ? bench.GetComponent<CraftingStation>() : null);
            }

            var named = (Dictionary<int, GameObject>)AccessTools.Field(typeof(ZNetScene), "m_namedPrefabs").GetValue(scene);
            PieceTable table = hammer.GetComponent<ItemDrop>().m_itemData.m_shared.m_buildPieces;
            if (!scene.m_prefabs.Contains(_prefab)) scene.m_prefabs.Add(_prefab);
            named[_prefab.name.GetStableHashCode()] = _prefab; // lets it be placed and loaded from saves
            table.m_pieces.RemoveAll(p => p == null);   // (destroyed pieces left by an earlier copy, ours or another mod's)
            if (!table.m_pieces.Contains(_prefab)) table.m_pieces.Add(_prefab);
            _table = table;
            Synced.NeedsServer(_prefab);   // not in the build menu on a server without the mod (it would delete the machine)
        }

        /// <summary>The cost setting (the server's in multiplayer) on the piece. One that can't be read keeps the last good cost.</summary>
        internal static void ApplyCost()
        {
            Piece piece = _prefab != null ? _prefab.GetComponent<Piece>() : null;
            if (piece != null) DHack.Shared.Costs.Apply(piece, Cost.Value, Log);
        }

        private static GameObject Make(GameObject source, CraftingStation workbench)
        {
            GameObject go = Object.Instantiate(source, _holder.transform);
            go.name = PiecePrefab;
            Container container = go.GetComponent<Container>();
            if (container != null) Object.DestroyImmediate(container); // it is not storage

            int layer = LayerMask.NameToLayer("piece");
            if (layer < 0) layer = go.layer;
            Renderer[] chest = go.GetComponentsInChildren<Renderer>(true);
            foreach (Collider c in go.GetComponentsInChildren<Collider>(true)) Object.DestroyImmediate(c); // and its hitbox
            var hit = new GameObject("Hitbox") { layer = layer };
            hit.transform.SetParent(go.transform, false);
            var box = hit.AddComponent<BoxCollider>();
            box.center = new Vector3(0f, 1.13f, -0.02f);
            box.size = new Vector3(1.05f, 2.3f, 0.92f);

            // As with the materials: a model that fails to build leaves the chest's look, never an unregistered piece.
            try
            {
                ModelBuilder.Build(go.transform, ModelData.Parts, go.layer);
                foreach (Renderer r in chest) r.enabled = false; // hide the chest
            }
            catch (System.Exception e)
            {
                Debug.LogWarning($"{Name}: could not build the slot machine's look, it keeps the chest's: {e.Message}");
                Transform model = go.transform.Find("Model");
                if (model != null) Object.DestroyImmediate(model.gameObject);
            }

            // snap points on the corners of its base, as far as the plinth, the coin tray and the lever reach (the chest has none): a row
            // of machines stands side by side, lever clear of the next one
            DHack.Shared.SnapPoints.Clear(go);
            DHack.Shared.SnapPoints.Box(go, new Vector3(-0.61f, 0f, -0.65f), new Vector3(0.69f, 0f, 0.48f));

            Piece piece = go.GetComponent<Piece>();
            piece.m_name = "$slotmachine_piece";
            piece.m_description = "$slotmachine_piece_desc";
            piece.m_category = Piece.PieceCategory.Misc;
            piece.m_usage = Piece.UsageTagFlags.Furniture | Piece.UsageTagFlags.Decor;   // the game's build-menu tags: something to play, not storage like the chest it's copied from
            piece.m_craftingStation = workbench;
            // the cost setting (a server owner can change it); if neither it nor the default can be read, the chest's stays: never free to build
            if (!DHack.Shared.Costs.Apply(piece, Cost.Value, Log)) DHack.Shared.Costs.Apply(piece, DefaultCost, Log);
            try
            {
                Sprite picture = DHack.Shared.Icon.Make(go);
                if (picture != null) piece.m_icon = picture;
            }
            catch (System.Exception e) { Debug.LogWarning($"{Name}: could not draw the build-menu picture: {e.Message}"); }
            go.AddComponent<SlotMachinePiece>();
            return go;
        }

        internal static void Unregister()
        {
            if (_prefab == null) return;
            if (ZNetScene.instance != null)
            {
                ZNetScene.instance.m_prefabs.Remove(_prefab);
                var named = (Dictionary<int, GameObject>)AccessTools.Field(typeof(ZNetScene), "m_namedPrefabs").GetValue(ZNetScene.instance);
                int hash = _prefab.name.GetStableHashCode();
                if (named.TryGetValue(hash, out GameObject current) && current == _prefab) named.Remove(hash); // only our own entry
            }
            GameObject hammer = ObjectDB.instance != null ? ObjectDB.instance.GetItemPrefab("Hammer") : null;
            PieceTable table = _table ?? (hammer != null ? hammer.GetComponent<ItemDrop>().m_itemData.m_shared.m_buildPieces : null);
            table?.m_pieces.RemoveAll(p => p == null || p == _prefab);
            _table = null;
            _prefab = null;
            Object.Destroy(_holder);
            _holder = null;
            Look.Clear();
        }
    }

    [HarmonyPatch(typeof(ZNetScene), "Awake")]
    internal static class ZNetScene_Awake
    {
        private static void Postfix(ZNetScene __instance) => Plugin.Register(__instance);
    }

    // Whichever of ZNetScene and ObjectDB wakes second, the piece is registered before any saved one is loaded.
    [HarmonyPatch(typeof(ObjectDB), "Awake")]
    internal static class ObjectDB_Awake
    {
        private static void Postfix() { if (ZNetScene.instance != null) Plugin.Register(ZNetScene.instance); }
    }

    // Logging out mid-spin: put the winnings in the inventory before the character is saved.
    // (Game.Shutdown runs on logout and quit, just before it saves; the autosave goes through SavePlayerProfile alone.)
    [HarmonyPatch(typeof(Game), "Shutdown")]
    internal static class Game_Shutdown
    {
        private static void Prefix() => SlotMachinePiece.PayOwed();
    }
}
